sys_script.script:
(function executeRule(current, previous) {

    var TARGET_TABLE =
        'x_snc_campusmatch_campusmatch_item';

    var USER_IMAGE_TABLE =
        'ZZ_YY' + TARGET_TABLE;


    // Only handle the CampusMatch "image" user_image field
    if (
        current.getValue('table_name') != USER_IMAGE_TABLE ||
        current.getValue('file_name') != 'image'
    ) {
        return;
    }


    /*
     * If this Business Rule fired because of UPDATE,
     * continue only when this attachment has JUST
     * become the CampusMatch user_image attachment.
     */
    if (
        current.operation() == 'update' &&
        !current.table_name.changesTo(USER_IMAGE_TABLE) &&
        !current.file_name.changesTo('image')
    ) {
        return;
    }


    var contentType =
        current.getValue('content_type') || '';

    if (current.getValue('file_name') != 'image')
        return;

    var contentType =
        current.getValue('content_type') || '';

    if (contentType.indexOf('image/') != 0)
        return;

    // Get the CampusMatch Item
    var item = new GlideRecord(TARGET_TABLE);

    if (!item.get(current.getValue('table_sys_id')))
        return;

    // Support JPG / PNG images
    var extension;

    if (contentType == 'image/png') {
        extension = '.png';
    }
    else if (
        contentType == 'image/jpeg' ||
        contentType == 'image/jpg'
    ) {
        extension = '.jpg';
    }
    else {
        return;
    }

    // Unique name for AI-processing copy
    var newFileName =
        'campusmatch_ai_' +
        current.getUniqueValue() +
        extension;

    // Prevent duplicate copy
    var existing = new GlideRecord('sys_attachment');

    existing.addQuery('table_name', TARGET_TABLE);
    existing.addQuery(
        'table_sys_id',
        current.getValue('table_sys_id')
    );
    existing.addQuery('file_name', newFileName);
    existing.setLimit(1);
    existing.query();

    if (existing.next())
        return;

    // Copy user_image into a normal attachment
    var gsa = new GlideSysAttachment();

    var stream =
        gsa.getContentStream(
            current.getUniqueValue()
        );

    if (!stream)
        return;

    var newAttachmentId =
        gsa.writeContentStream(
            item,
            newFileName,
            contentType,
            stream
        );

    // ONLY signal AI processing after copy was successful
    if (newAttachmentId) {

        item.setValue('ai_ready', true);
        item.setValue('ai_processed', false);
        item.update();

        gs.info(
            'CampusMatch AI attachment created: ' +
            newAttachmentId +
            ' | AI Ready set to true for item: ' +
            item.getUniqueValue()
        );
    }

})(current, previous);
